/* @lc app=leetcode id=2055 lang=kotlin */
class Solution { fun platesBetweenCandles(s: String, queries: Array<IntArray>): IntArray = IntArray(s.length).let { pSum -> IntArray(s.length).let { lC -> IntArray(s.length).let { rC -> s.indices.fold(-1) { acc, i -> (if (s[i] == '|') i else acc).also { lC[i] = it } }.run { s.indices.reversed().fold(-1) { acc, i -> (if (s[i] == '|') i else acc).also { rC[i] = it } } }.run { s.indices.fold(0) { acc, i -> (acc + if (s[i] == '*') 1 else 0).also { pSum[i] = it } } }.run { IntArray(queries.size) { i -> rC[queries[i][0]].let { l -> lC[queries[i][1]].let { r -> if (l != -1 && r != -1 && l < r) pSum[r] - pSum[l] else 0 } } } } } } }